import{R as t,e as o,f as a,U as r}from"./chunks/framework.ywem4qy5.js";const h=JSON.parse('{"title":"Google Places","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/address-providers/google-places.md","filePath":"integrations/address-providers/google-places.md","lastUpdated":1775908585000}'),s={name:"integrations/address-providers/google-places.md"};function l(n,e,i,d,c,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="google-places" tabindex="-1">Google Places <a class="header-anchor" href="#google-places" aria-label="Permalink to &quot;Google Places&quot;">​</a></h1><p>Use <a href="https://developers.google.com/maps/documentation/javascript/places-autocomplete" target="_blank" rel="noreferrer">Google Places Autocomplete</a> to use their service to suggest addresses.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Address Providers</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Google Places as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-google-places-api" tabindex="-1">Step 2. Connect to the Google Places API <a class="header-anchor" href="#step-2-connect-to-the-google-places-api" aria-label="Permalink to &quot;Step 2. Connect to the Google Places API&quot;">​</a></h3><ol><li>Go to the <a href="https://console.cloud.google.com/project/_/apiui/apis/enabled" target="_blank">Google Cloud Platform Console</a>.</li><li>Click the <strong>Select a project</strong> button. Either create a new project, or select an existing one.</li><li>Select <strong>Credentials</strong> from the left side menu, and click <strong>+ Create Credentials</strong>, selecting <strong>API Key</strong>.</li><li>From the left side menu, select <strong>Library</strong>.</li><li>From the list of APIs enable both <strong>Places API</strong> and <strong>Maps JavaScript API</strong>. <ul><li>If using the <strong>Show Current Location Button</strong> setting for your field, also add <strong>Geocoding API</strong>.</li></ul></li></ol><h3 id="step-3-field-setting" tabindex="-1">Step 3. Field Setting <a class="header-anchor" href="#step-3-field-setting" aria-label="Permalink to &quot;Step 3. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add an <strong>Address</strong> field to your form.</li><li>Enable the <strong>Auto-Complete</strong> sub-field option.</li><li>Select Google Places for the <strong>Auto-Complete Integration</strong>.</li></ol><p>You can also provide <a href="https://developers.google.com/maps/documentation/javascript/places-autocomplete#add-autocomplete" target="_blank" rel="noreferrer">Options</a> in the table field. The <code>value</code> content must be valid JSON, so ensure you encase strings in <code>&quot;</code> characters. For example, the below might restrict suggested addresses to Australia.</p><table tabindex="0"><thead><tr><th>Option</th><th>Value</th></tr></thead><tbody><tr><td><code>componentRestrictions</code></td><td><code>{ &quot;country&quot;: &quot;au&quot; }</code></td></tr><tr><td><code>requestedRegion</code></td><td><code>&quot;au&quot;</code></td></tr></tbody></table>',10)])])}const u=t(s,[["render",l]]);export{h as __pageData,u as default};
